```zig
const std = @import("std");
const rl = @import("raylib");
const net = std.net;
const posix = std.posix;
const mem = std.mem;

pub const ControllerEventIdx = enum(u8) {
    ANALOG_LX = 0,
    ANALOG_LY = 1,
    ANALOG_RX = 2,
    ANALOG_RY = 3,
    L1 = 4,
    L2 = 5,
    R1 = 6,
    R2 = 7,
    TRIANGLE = 8,
    CROSS = 9,
    SQUARE = 10,
    CIRCLE = 11,
    UP = 12,
    DOWN = 13,
    LEFT = 14,
    RIGHT = 15,
    SELECT = 16,
    START = 17,
};

// ─── Build the binary message ───

fn buildMessage(events: []const [2]i16) ![]u8 {
    var out = std.ArrayList(u8).init(std.heap.page_allocator);
    defer out.deinit();

    // --- Header ---
    try out.appendInt(events.len, .big);          // num_events (uint32)
    try out.appendInt(events.len, .big);          // msg_len placeholder (we'll overwrite below)
    // Actually we store num_events first, then compute msg_len after writing events

    // Re-do header properly:
    // We'll just write everything then fix header.
    _ = out.items; // clear

    var buffer = std.ArrayList(u8).init(std.heap.page_allocator);
    defer buffer.deinit();

    // num_events
    try buffer.appendInt(events.len, .big);
    // msg_len = 16 (header) + 24 * events.len
    const msg_len = 16 + 24 * events.len;
    try buffer.appendInt(msg_len, .big);

    // Events
    for (events) |pair| {
        const type: u8 = @intCast(pair.0);
        const val: i32 = pair.1;
        // type (4 bytes big-endian) + value (4 bytes big-endian) + 12 zero bytes padding = 24
        try buffer.appendUint(type, 32, .big);
        try buffer.appendInt(val, .big);
        // pad to 24
        var pad_buf = std.ArrayList(u8).init(std.heap.page_allocator);
        defer pad_buf.deinit();
        for (0..12) |j| try pad_buf.append(0);
        try pad_buf.writeToAll(buffer);
    }

    const result = buffer.items;
    // Overwrite msg_len in header with actual computed value
    const header_ptr = result[0..4].ptr;
    const actual_len: u32 = msg_len cast u32;
    @memcpy(header_ptr, &actual_len, 4);
    return result;
}

// ─── Parse helper (mirrors server logic) ───

fn parseMessage(data: []const u8) ![]const u8 {
    if (data.len < 16) return error.BadMessageLength;

    const num_events = @intCast(data[0..4][0]) cast u32;
    const msg_len = @intCast(data[4..8][0]) cast u32;

    if (msg_len != 16 + 24 * num_events) return error.MismatchedLength;

    var parsed = std.ArrayList(u8).init(std.heap.page_allocator);
    defer parsed.deinit();

    var pos = 8; // skip header

    for (0..num_events) |i| {
        if (pos + 24 > data.len) return error.IncompleteMessage;

        const type: u8 = @intCast(data[pos..][0]) cast u8;
        const val: i32 = @intFromSlice(i32, data[pos+4..pos+8], .big);

        // Map type -> index into our known table (same as server)
        const idx = mapEventType(type);
        if (idx >= 0) {
            std.debug.print("client sent event[{s}]={d}\n", .{ @tagName(ControllerEventIdx(@intCast(type))), val });
        }

        pos += 24;
    }

    // Return a slice starting right after header for inspection
    return data[8..];
}

const EventTypeTable = [_]u8{
    0, // ABS_X
    1, // ABS_Y
    2, // ABS_RX
    3, // ABS_RY
    4, // BTN_TL
    5, // BTN_TL2
    6, // BTN_TR
    7, // BTN_TR2
    8, // BTN_NORTH
    9, // BTN_SOUTH
    10, // BTN_WEST
    11, // BTN_EAST
    12, // BTN_DPAD_UP
    13, // BTN_DPAD_DOWN
    14, // BTN_DPAD_LEFT
    15, // BTN_DPAD_RIGHT
    16, // BTN_SELECT
    17, // BTN_START
};

fn mapEventType(type: u8) i8 {
    // Returns negative if unknown type
    const expected = @as(u8, @intCast(@as(u16, 0) >> 8 | @as(u8, @intCast(@as(u16, 0) & 0xFF)))) :: else undefined;
    // Simpler: compare against known types directly
