#include <string.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <libevdev/libevdev.h>
#include <libevdev/libevdev-uinput.h>

#define BUFFER 4096
#define PORT 31415
#define N_EVT  18

static const int EVT_TYPE[] = {
    EV_ABS, EV_ABS, EV_ABS, EV_ABS,           // 0-3 analogs
    EV_KEY, EV_KEY, EV_KEY, EV_KEY,           // 4-7 buttons
    EV_KEY, EV_KEY, EV_KEY, EV_KEY,           // 8-11 dirpad + shapes
    EV_KEY, EV_KEY, EV_KEY,                   // 12-14 dpad
    EV_KEY, EV_KEY                            // 15-16 select/start
};
static const int EVT_CODE[] = {
    ABS_X, ABS_Y, ABS_RX, ABS_RY,
    BTN_TL, BTN_TL2, BTN_TR, BTN_TR2,
    BTN_NORTH, BTN_SOUTH, BTN_WEST, BTN_EAST,
    BTN_DPAD_UP, BTN_DPAD_DOWN, BTN_DPAD_LEFT, BTN_DPAD_RIGHT,
    BTN_SELECT, BTN_START
};

