static void udp(void) {
    int s = socket(AF_INET, SOCK_DGRAM, 0);
    struct sockaddr_in sa; memset(&sa, 0, sizeof(sa));
    sa.sin_family = AF_INET; sa.sin_addr = INADDR_ANY; sa.sin_port = htons(PORT);
    bind(s, (struct sockaddr *)&sa, sizeof(sa));

