        if (n < 0) continue;

        const u8 *p = (const u8 *)buf;
        u32 ne = get_u32_le(p);                      // little-endian count
        const u8 *e = p + 4;
        u32 read = 4;

        for (u32 i = 0; i < ne; ) {
            u8 idx = e[read];
            i32 val = get_i32_le(e + 1 + read);      // 4-byte signed int
            read += 8;
