        state[5].?.[1] = if (rl.isKeyDown(rl.KeyboardKey.key_l)) 1 else 0;           // L2
        state[12].?.[1] = if (rl.isKeyDown(rl.KeyboardKey.key_up)) 1 else 0;         // UP
        state[13].?.[1] = if (rl.isKeyDown(rl.KeyboardKey.key_down)) 1 else 0;        // DOWN
        state[14].?.[1] = if (rl.isKeyDown(rl.KeyboardKey.key_left)) 1 else 0;        // LEFT
